select count(1)
from master_data_item
where tenant_id = #{tenantId}
  and category = #{category}
  and deleted = 0

  and (item_code like concat('%', #{keyword}, '%') or item_name like concat('%', #{keyword}, '%'))

mapper.update:
update master_data_item
set status = 'DISABLED',
    updated_at = now()
where id = #{id}
  and tenant_id = #{tenantId}
  and category = #{category}
  and deleted = 0

update master_data_item
set deleted = 1,
    updated_at = now()
where id = #{id}
  and tenant_id = #{tenantId}
  and category = #{category}
  and deleted = 0
